739	// ── New session wizard ────────────────────────────────────────────────────────
740	
741	/// A 4-step panel drawn over the bottom of the screen. Each completed step
742	/// stays visible with its confirmed value while the user fills the next one.
743	fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
744	    const LABEL_W: usize = 24;
745	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
746	    const PANEL_H: usize = 7;
747	
748	    let panel_top = h.saturating_sub(PANEL_H + 1);
749	
750	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
751	    let mut agent_sel = 0usize;
752	    let mut confirmed_agent = 0usize;
753	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
754	
755	    execute!(stdout, cursor::Show).ok();
756	
757	    loop {
758	        // ── Draw panel ────────────────────────────────────────────────────────
759	        // Title row
760	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
761	        write!(stdout, "\x1b[1;38;5;229m  New Session\x1b[0m").ok();
762	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
763	
764	        // Blank separator
765	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
766	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
767	
768	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
769	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
770	
771	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
772	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
773	            let lpart = format!("{label:<LABEL_W$}");
774	
775	            if i < step {
776	                // Completed — dim label, value in colour
777	                let val = if i == 0 {
778	                    let (name, _, col) = AGENTS[confirmed_agent];
779	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
780	                } else {
781	                    let v = inputs[i - 1].trim();
782	                    if v.is_empty() { "\x1b[38;5;238m(skip)\x1b[0m".to_string() }
783	                    else            { format!("\x1b[38;5;255m{v}\x1b[0m") }
784	                };
785	                write!(stdout, "\x1b[38;5;240m{lpart}\x1b[0m{val}").ok();
786	            } else if i == step {
787	                // Active step
788	                write!(stdout, "\x1b[38;5;255m{lpart}\x1b[0m").ok();
789	                if i == 0 {
790	                    // Inline agent picker
791	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
792	                        if ai > 0 { write!(stdout, "\x1b[38;5;238m │ \x1b[0m").ok(); }
793	                        if ai == agent_sel {
794	                            write!(stdout, "\x1b[48;5;236;38;5;{col}m {name} \x1b[0m").ok();
795	                        } else {
796	                            write!(stdout, "\x1b[38;5;240m {name}\x1b[0m").ok();
797	                        }
798	                    }
799	                } else {
800	                    // Text input — print typed chars, terminal cursor sits here
801	                    write!(stdout, "\x1b[38;5;255m{}\x1b[0m", inputs[i - 1]).ok();
802	                }
803	            } else {
804	                // Future step — very dim label only
805	                write!(stdout, "\x1b[38;5;238m{lpart}\x1b[0m").ok();
806	            }
807	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
808	        }
809	
810	        // Trailing blank row
811	        let blank2 = panel_top + 6;
812	        if blank2 < h.saturating_sub(1) {
813	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
814	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
815	        }
816	
817	        // Status bar hint
818	        let bar = if step == 0 {
819	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
820	        } else {
821	            "  type to enter   enter: next   esc: cancel  "
822	        };
823	        draw_status(stdout, bar, w, h).ok();
824	
825	        // Position terminal cursor for text input steps
826	        if step > 0 {
827	            let row = step_rows[step];
828	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
829	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
830	        }
831	        stdout.flush().ok();
832	
833	        // ── Handle input ──────────────────────────────────────────────────────
834	        match event::read().ok()? {
835	            Event::Key(k) => match k.code {
836	                KeyCode::Esc => {
837	                    execute!(stdout, cursor::Hide).ok();
838	                    return None;
839	                }
840	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
841	                    if agent_sel > 0 { agent_sel -= 1; }
842	                }
843	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
844	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
845	                }
846	                KeyCode::Backspace if step > 0 => {
847	                    inputs[step - 1].pop();
848	                }
849	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
850	                    inputs[step - 1].push(c);
851	                }
852	                KeyCode::Enter => match step {
853	                    0 => { confirmed_agent = agent_sel; step = 1; }
854	                    1 | 2 => { step += 1; }
855	                    _ => {
856	                        execute!(stdout, cursor::Hide).ok();
857	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
858	                        let branch_raw = inputs[0].trim().to_string();
859	                        return Some(NewSessionConfig {
860	                            agent_name: agent_name.to_string(),
861	                            agent_cli: agent_cli.to_string(),
862	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
863	                            session_name: inputs[1].trim().to_string(),
864	                            prompt: inputs[2].trim().to_string(),
865	                            repo_dir: repo_dir.to_string(),
866	                        });
867	                    }
868	                },
869	                _ => {}
870	            },
871	            _ => {}
872	        }
873	    }
874	}
