878	fn create_worktree(repo_dir: &str, branch: &str) -> String {
879	    let repo_path = std::path::Path::new(repo_dir);
880	    let parent = match repo_path.parent() {
881	        Some(p) => p,
882	        None => return "Error: cannot determine repo parent directory".to_string(),
883	    };
884	    let repo_name = repo_path
885	        .file_name()
886	        .map(|s| s.to_string_lossy().to_string())
887	        .unwrap_or_else(|| "repo".to_string());
888	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
889	
890	    // Try -b (new branch) first; fall back to checking out an existing branch.
891	    let out = std::process::Command::new("git")
892	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
893	        .current_dir(repo_dir)
894	        .output();
895	
896	    match out {
897	        Err(e) => format!("Error: {e}"),
898	        Ok(o) if o.status.success() => {
899	            format!("Created worktree: {}", short_path_s(wt_path.to_str().unwrap_or("")))
900	        }
901	        Ok(o) => {
902	            let msg = String::from_utf8_lossy(&o.stderr);
903	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
904	            format!("Error: {first}")
905	        }
906	    }
907	}
