fn draw(
    stdout:   &mut impl Write,
    flat:     &[(usize, String)],
    starts:   &[usize],
    sel:      usize,
    line_sel: usize,
    scroll:   usize,
    h:        usize,
    w:        usize,
    total:    usize,
    flash:    Option<&str>,
) -> io::Result<()> {
    const SEL_BG:  &str = "48;5;236";   // card selection — dark grey
    const LINE_BG: &str = "48;5;240";   // active line within card — lighter grey

    let end = (scroll + h).min(flat.len());

    for row in 0..h {
        // Clear the whole row first so tabs and short lines never leave stale chars.
        execute!(stdout, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;

        let flat_idx = scroll + row;
        if flat_idx < end {
            let (card_idx, line) = &flat[flat_idx];
            let is_sel_card = *card_idx == sel;
            let is_sel_line = flat_idx == line_sel;

            if is_sel_line {
                let line_bg = with_bg(line, LINE_BG);
                let vis = visible_width(line);
                let pad = w.saturating_sub(vis);
                write!(stdout, "\x1b[{LINE_BG}m{line_bg}{}\x1b[0m", " ".repeat(pad))?;
            } else if is_sel_card {
                let line_bg = with_bg(line, SEL_BG);
                let vis = visible_width(line);
                let pad = w.saturating_sub(vis);
                write!(stdout, "\x1b[{SEL_BG}m{line_bg}{}\x1b[0m", " ".repeat(pad))?;
            } else {
                write!(stdout, "{line}")?;
            }
        }
    }

    // Status bar
    let card_start = starts[sel];
    let card_end   = starts.get(sel + 1).copied().unwrap_or(flat.len());
    let card_line  = line_sel.saturating_sub(card_start) + 1;
    let card_total = card_end.saturating_sub(card_start);
    let base = format!(
        "  {}/{} msgs  line {}/{}  j/k card  ↑↓ line  u/PgDn page  g/G ends  y/c copy  r resume  d delete  q quit  ",
        sel + 1, total, card_line, card_total,
    );
    let bar = if let Some(msg) = flash {
        let skip = msg.chars().count();
        let rest: String = base.chars().skip(skip).collect();
        format!("{msg}{rest}")
    } else {
        base
    };
    let bar_display: String = bar.chars().take(w).collect();
    let padded = format!("{:width$}", bar_display, width = w);
    execute!(stdout, cursor::MoveTo(0, h as u16))?;
    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;

    stdout.flush()
}

